    "var fields = $vars." + IXP_NODE_ID + ".output.ExtractionResult.ResultsDocument.Fields || [];\n"
    "var vendorName = fields.find(function(f) { return f.FieldName === '" + FIELD_VENDOR + "'; });\n"
    "var vendorStr = vendorName ? vendorName.Values[0] : 'Unknown';\n"
    "var totalAmt = fields.find(function(f) { return f.FieldName === '" + FIELD_TOTAL + "'; });\n"
    "var totalStr = totalAmt ? totalAmt.Values[0] : 'Unknown';\n"
